    def __init__(self, principal, rights, deny=False, inherited=False):
        self.principal = principal
        self.rights = frozenset(rights)
        self.deny = deny
        self.inherited = inherited

    def __repr__(self):
        return "Ace(%r, %r, deny=%r, inherited=%r)" % (
            self.principal,
            sorted(self.rights),
            self.deny,
            self.inherited,
        )


def run(path, *args):
    """对 ``path`` 执行 icacls，返回标准输出。"""
    cmd = [ICACLS, path] + [str(a) for a in args]
    proc = subprocess.run(cmd, capture_output=True, text=True, errors="replace")
    if proc.returncode != 0:
        detail = " ".join(
            part.strip() for part in (proc.stdout, proc.stderr) if part and part.strip()
        )
        raise ICaclsError("icacls %s failed with %d: %s" % (path, proc.returncode, detail))
    return proc.stdout


def _looks_like_principal(text):
    """``text`` 是否像一个安全主体名（而不是路径残留）。"""
    if not text or ":" in text or text.startswith("\\"):
        return False
    if _SID_RE.match(text):
        return True
    match = _DOMAIN_QUALIFIED_RE.match(text)
    if match:
        domain = match.group(1).strip()
        return " " not in domain or domain.upper() in _MULTIWORD_DOMAINS
    return " " not in text


def _path_prefixes(path):
    """``path`` 可能的几种写法，用于剥掉 icacls 回显的前缀。"""
    candidates = []
    seen = set()
    for raw in (path, os.path.normpath(path), os.path.abspath(path)):
        for variant in (raw, raw.rstrip("\\/")):
            if variant and variant.lower() not in seen:
                seen.add(variant.lower())
                candidates.append(variant)
    return candidates


def _strip_path_prefix(principal, path=None):
    """去掉 ``principal`` 前面被 icacls 一起打印出来的对象路径。"""
    text = principal.strip()
    lowered = text.lower()
    if path is not None:
        try:
            path = os.fspath(path)
        except TypeError:
            path = str(path)
        for prefix in _path_prefixes(path):
            low = prefix.lower()
            if not lowered.startswith(low):
                continue
            # 前缀必须完整占到一个词边界，否则短路径会吃掉主体名的一部分。
            if len(low) < len(lowered) and lowered[len(low)] not in " \t":
                continue
            rest = text[len(prefix) :].strip()
            if rest:
                return rest
    if not _PATH_ROOT_RE.match(text):
        return text
    # 拿不到路径时按空白逐段尝试：路径里可以有空格，主体名里通常没有。
    tokens = text.split()
    for index in range(1, len(tokens)):
        candidate = " ".join(tokens[index:])
        if _looks_like_principal(candidate):
            return candidate
    if len(tokens) > 1:
        return " ".join(tokens[1:])
    return text


def parse_aces(output, path=None):
    """把 icacls 的输出解析成 :class:`Ace` 列表。

    ``path`` 是本次查询的对象路径（可选）：icacls 会把它回显在首行开头，
    给出该参数即可精确剥离；未给出时按路径的形状做启发式剥离。
    """
    aces = []
    for line in output.splitlines():
        m = _ACE_RE.match(line)
        if not m:
            continue
        principal = _strip_path_prefix(m.group(1), path)
        tokens = []
        for chunk in _TOKEN_RE.findall(m.group(2)):
            for part in chunk.split(","):
                part = part.strip().upper()
                if part:
                    tokens.append(part)
        deny = "DENY" in tokens
        inherited = "I" in tokens
        rights = {
            t for t in tokens if t not in _INHERITANCE_FLAGS and t not in ("DENY", "I")
        }
        if not principal or not rights:
            continue
        aces.append(Ace(principal, rights, deny=deny, inherited=inherited))
    return aces


def list_aces(path):
    """返回 ``path`` 上的全部访问控制项（含从父级继承来的项）。"""
    return parse_aces(run(path), path)


def list_explicit_aces(path):
    """返回 ``path`` 上**显式设置**的访问控制项。

    从父目录继承来的项不算显式设置：icacls 在输出里用 ``(I)`` 标记它们。
    """
    return [ace for ace in list_aces(path) if not ace.inherited]


def deny(path, principal, spec, recursive=False):
    """在 ``path`` 上为主体添加一条拒绝项。

    ``spec`` 是 icacls 的权限说明，例如 ``"(OI)(CI)(RX)"``。
    ``recursive`` 为真时加上 ``/T``，让已经存在的整棵子树都拿到这条拒绝项；
    ``spec`` 里的 ``(OI)(CI)`` 则负责让之后新建的条目继承它。
    """
    args = ["/deny", "%s:%s" % (principal, spec)]
    if recursive:
        args.append("/T")
    return run(path, *args)


def grant(path, principal, spec, recursive=False):
    """在 ``path`` 上为主体添加一条允许项。"""
    args = ["/grant", "%s:%s" % (principal, spec)]
    if recursive:
        args.append("/T")
    return run(path, *args)


def disable_inheritance(path):
    """移除 ``path`` 上从父目录继承来的项。"""
    return run(path, "/inheritance:r")
